(()=>{const t=document.querySelector("[data-portfolio-home]");if(!t)return;const e=t.querySelector("[data-home-filters]"),n=[...t.querySelectorAll("[data-home-topic]")];if(!e||!n.length)return;e.hidden=!1;const s=t=>{const s=t.dataset.homeFilter;e.querySelectorAll("[data-home-filter]").forEach(e=>{e.setAttribute("aria-pressed",String(e===t))}),n.forEach(e=>{e.hidden=s!=="all"&&e.dataset.homeTopic!==s})};e.addEventListener("click",t=>{const n=t.target.closest("[data-home-filter]");n&&e.contains(n)&&s(n)}),t.addEventListener("click",n=>{const o=n.target.closest('a[href="#reading"]');o&&t.querySelector("#reading").hidden&&s(e.querySelector('[data-home-filter="all"]'))})})()